      SUBROUTINE CABD2(RC,TC,RA,TA,RB,RBV,TBV)CC     COMPUTES RCV AND RCV FROM PRELIMINARY CALCULATIONSCC     LIST OF COMMON BLOCKSC      INCLUDE 'TMUL.CIN'CC     LOCAL VARIABLESC      REAL  RA(6,6), RB(6,6), RBV(6,6), RC(6,6)      REAL  TA(5,21), TBV(5,21), TC(5,21)CC-------------------------------------------------------      CALL CAB(RC,RA,RBV)C      DO 20 I1 = 1, 5      DO 20 I23 = 1, 21      S = 0.0      DO 10 I4 = 1, 5      S = S + RA(I1,I4)*TBV(I4,I23)   10 CONTINUE      TC(I1,I23) = S   20 CONTINUEC      TMUL = .FALSE.      TMULT = .FALSE.      DO 30 I1 = 1, 5      DO 30 I23 = 1, 21      IF (TA(I1,I23) .NE. 0.0) THEN        TMUL = .TRUE.        IF (I1 .LE. 4) TMULT = .TRUE.        GO TO 40      ENDIF   30 CONTINUEC   40 IF (.NOT. TMUL) GO TO 100      IF (TMULT) THEN        I1MIN = 1      ELSE        I1MIN = 5      ENDIFC      DO 80 I1 = I1MIN, 5      DO 80 I2 = 1, 6      INDA = 0      DO 80 I5 = 1, 6      TRR = 0.0      TRRV = 0.0      DO 50 I4 = 1, I5      INDA  = INDA + 1      TRR = TRR + TA(I1,INDA)*RB(I4,I2)      TRRV = TRRV + TA(I1,INDA)*RBV(I4,I2)   50 CONTINUEC      IF (TRR .EQ. 0.0 .AND. TRRV .EQ. 0.0) GO TO 80      DO 60 I3 = 1, 6      I23 = INDEX2(I2,I3)      TC(I1,I23) = TC(I1,I23) + TRRV*RB(I5,I3) + TRR*RBV(I5,I3)   60 CONTINUE   80 CONTINUEC  100 RETURN      END